    </div>
  );
}

instruction.text:
## Componente, props e callback prop

```tsx
type TaskItemProps = {
  task: Task;
  onRemove: (id: number) => void;
};

function TaskItem({ task, onRemove }: TaskItemProps) {
  return (
    <li>
      {task.text}
      <button onClick={() => onRemove(task.id)}>Remover</button>
    </li>
  );
}
```

- `type TaskItemProps` é a **lista de encaixes** da peça
- o pai usa a peça como uma tag: `<TaskItem key={task.id} task={task} onRemove={removeTask} />`
- prop que é função de aviso começa com **`on`**
- o dado mora na peça **mais alta** que precisa dele: `tasks` fica no `App`, porque a lista e o contador usam

spec.starter:
// useState e useEffect já estão disponíveis — não precisa importar.

type Task = { id: number; text: string };

// crie o TaskItem aqui

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([
    { id: 1, text: "Estudar React" },
    { id: 2, text: "Beber água" },
    { id: 3, text: "Revisar a aula 4" },
  ]);

  function removeTask(id: number) {
    setTasks(tasks.filter((task) => task.id !== id));
  }

  return (
    <ul className="p-4">
      {tasks.map((task) => (
        <li key={task.id}>
          {task.text} <button onClick={() => removeTask(task.id)}>Remover</button>
        </li>
      ))}
    </ul>
  );
}

